X.plGroup('🫧 泡泡', 'gysBubble', [
    ['bb.msg', 'TA 在泡泡上给粉丝发消息', 'TA 自己发泡泡 / 你点「催更」', '{{我是谁}} {{她}} {{时间}} {{特别}} {{最近}} {{之前}} {{回复}} {{条数}}'],
